{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목을 보여 주는 정보를 바탕으로 인덱스를 추가할 컬럼을 판단했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 느렸던 상황",
          "task": "조회 성능 개선에 필요한 인덱스 컬럼을 판단하는 일",
          "action": "실행 계획이나 조회 조건에서 인덱스 컬럼 선택에 영향을 준 정보를 설명",
          "result": "관찰한 정보가 해당 컬럼을 선택할 근거가 된 이유"
        },
        "expectedEvidence": [
          "인덱스를 추가할 컬럼을 정할 때 참고한 구체적인 정보",
          "그 정보가 나타난 실행 계획이나 실제 조회 조건",
          "관찰한 정보와 선택한 컬럼 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 개선할 때, 어느 컬럼에 인덱스를 추가할지는 무엇을 보고 정하셨나요?",
      "answerTip": "당시 확인했던 자료를 떠올리며 본인의 판단을 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 조회 쿼리의 실제 조회 조건이나 실행 계획에서 확인한 정보를 구체적으로 설명하고, 그 정보가 인덱스 컬럼 선택으로 이어진 이유를 밝힌다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 조건이나 실행 계획을 참고해 인덱스 컬럼을 정한다고 설명하지만, 신고 목록 조회 쿼리에서 실제로 확인한 정보는 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회 쿼리에 인덱스를 추가했다는 사실이나 개선 수치만 반복하고, 컬럼 선택에 참고한 정보는 제시하지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 오류를 추적하며 로그의 구체적인 단서로 초기 추정을 수정하고 원인을 좁혔는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의가 들어왔고 처음에는 클라이언트 문제로 추정했던 상황",
          "task": "로그를 통해 처음 추정이 맞는지 판단하는 일",
          "action": "처음 추정과 맞지 않았던 로그의 구체적인 단서를 설명",
          "result": "그 단서가 클라이언트 문제라는 추정을 바꾸게 한 지점"
        },
        "expectedEvidence": [
          "클라이언트 문제라는 초기 추정을 바꾸게 한 구체적인 로그 단서",
          "해당 단서를 드러낸 로그 기록의 시간 관계나 실행 주체 등 식별 정보",
          "그 단서가 초기 추정과 맞지 않았던 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 두 번 발송됐을 때, 클라이언트 문제라는 처음 추정을 바꾸게 한 로그의 단서는 무엇이었나요?",
      "answerTip": "기억나는 관찰 사실과 당시의 추정을 구분해서 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 중복 발송 로그에서 확인한 기록의 시간 관계나 실행 주체 등 구체적인 단서를 제시하고, 그것이 클라이언트 문제라는 추정과 맞지 않는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 중복 발송 로그에서 서버 측 문제를 확인했다고 설명하지만, 처음 추정을 바꾸게 한 구체적인 기록이나 식별 정보는 제시하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송의 원인이 스케줄러 중복 실행이었다는 결론이나 잠금 조치만 말하고, 추정을 바꾼 로그 단서는 제시하지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요구사항의 구현 범위를 조정할 때 포함 여부를 가르는 구체적인 판단 기준을 세웠는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 구현 범위를 조정하던 상황",
          "task": "요구사항 중 어디까지 구현할지 판단해야 했던 지점",
          "action": "구현 범위를 정하는 데 적용한 기준과 해당 요구사항에 그 기준을 적용한 이유",
          "result": "그 기준에 따라 구분된 구현 범위"
        },
        "expectedEvidence": [
          "요구사항의 구현 범위를 정할 때 실제로 적용한 판단 기준",
          "그 기준을 적용한 구체적인 요구사항",
          "해당 요구사항이 기준에 부합하거나 부합하지 않는다고 본 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정할 때, 요구사항을 어디까지 구현할지 정한 기준은 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 짚고 본인이 내린 판단에 집중해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 가른 기준을 구체적으로 밝히고, 실제 요구사항 하나에 그 기준이 어떻게 적용됐는지 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항의 중요도나 개발 여건 등 일반적인 기준은 말하지만, 실제 구현 범위를 가른 지점은 구체적으로 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항의 구현 범위를 정한 기준을 제시하지 않거나, 인터뷰 실시와 문서 작성 사실만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면설계서에서 예외 상황을 사용자가 보게 될 구체적인 화면 상태로 정했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예외 상황을 포함한 화면설계서를 작성하던 상황",
          "task": "예외 상황 하나에서 사용자가 보게 될 화면을 정하는 일",
          "action": "선택한 예외 상황에 맞춰 화면에 나타낼 모습을 구체적으로 정한 판단",
          "result": "화면설계서에 담긴 해당 예외 화면의 모습"
        },
        "expectedEvidence": [
          "예외 상황 하나에서 보여주기로 정한 구체적인 화면 모습",
          "그 화면이 나타나는 예외 상황",
          "화면 요소의 표시 상태나 안내 표현 등 화면 모습을 구체화하는 세부"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서를 작성할 때, 예외 상황 하나를 사용자에게 어떤 화면으로 보여주기로 했나요?",
      "answerTip": "한 장면에 집중해 듣는 사람이 모습을 떠올릴 수 있게 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황 하나를 짚고, 그때 보여줄 화면을 요소의 표시 상태나 안내 표현 등으로 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 화면에서 오류를 알리거나 안내를 제공한다고 설명하지만, 사용자가 보게 될 화면 모습은 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황에서 보여줄 화면을 설명하지 못하거나, 화면설계서의 분량과 작성 도구만 이야기한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "진통제 처방의 이상을 알아차리고 투약을 보류한 판단에 구체적인 확인 근거가 있었는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제 처방을 받은 상황",
          "task": "처방에 따라 투약을 진행해도 되는지 판단해야 했음",
          "action": "당시 확인한 처방 내용을 비교 대상과 연결해 투약을 보류한 근거를 설명",
          "result": "담당의의 확인 전에는 투약하지 않기로 판단함"
        },
        "expectedEvidence": [
          "진통제 투약을 보류하기로 판단한 구체적인 근거",
          "이상 여부를 판단할 때 비교한 정보",
          "비교한 정보와 해당 처방 사이에서 확인한 차이"
        ]
      },
      "question": "정형외과 병동에서 수술 후 환자의 진통제 투약을 멈추고 담당의에게 확인했던 당시, 투약을 보류하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 짚고 본인이 판단한 부분을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방을 무엇과 비교했는지 구체적으로 밝히고, 확인한 차이가 투약 보류 판단으로 이어진 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 용량이 평소보다 많았다는 지원서 내용을 반복하거나, 의심스러운 처방은 확인해야 한다는 일반적인 근거에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 보류한 판단 근거를 제시하지 않거나, 담당의에게 확인한 이후의 이야기만 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자의 상태 변화를 이전 관찰과 구분할 수 있는 구체적인 정보로 간호 기록에 남겼는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 활력징후와 통증을 관찰하던 상황",
          "task": "이전 관찰과 달라진 환자 상태를 간호 기록에 남겨야 했음",
          "action": "실제 기록에서 상태 변화를 나타내기 위해 담은 정보를 설명",
          "result": "관찰 시점과 변화 내용이 드러나는 간호 기록"
        },
        "expectedEvidence": [
          "이전 관찰과 달라진 환자 상태에 대해 간호 기록에 남긴 정보",
          "관찰 시점을 구분할 수 있는 기록 내용",
          "이전 상태와 달라진 정도를 나타내는 관찰값이나 증상 표현"
        ]
      },
      "question": "정형외과 병동에서 수술 후 환자의 활력징후와 통증을 관찰하실 때, 이전 관찰과 달라진 상태는 간호 기록에 어떤 정보로 남기셨나요?",
      "answerTip": "여러 사례를 나열하기보다 기억나는 한 장면에 집중해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 환자 관찰 장면을 바탕으로 간호 기록에 담은 시점과 관찰값 또는 증상 표현을 제시해, 이전 상태와의 차이가 구체적으로 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "간호 기록에 활력징후나 통증 정도를 적는다고 설명하지만, 실제로 기록한 상태 변화의 구체적인 내용은 제시하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "환자 상태 변화에 관해 간호 기록에 남긴 정보를 제시하지 않거나, 기록과 무관한 업무만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "감속기 축의 지름을 결정한 근거를 통해 하중과 축의 지지 조건을 주요 치수 선정에 연결할 수 있는지 확인한다.",
        "questionType": "behavioral",
